extends Node

## Persists personal bests and lifetime stats to user://.

const SAVE_PATH := "user://ivory_beats.save.json"
const MODES := ["sprint", "endless", "blitz"]

var best: Dictionary = {"sprint": 0, "endless": 0, "blitz": 0}
var plays: int = 0
var total_hits: int = 0
var total_perfects: int = 0
var best_combo: int = 0


func _ready() -> void:
	load_data()


func load_data() -> void:
	if not FileAccess.file_exists(SAVE_PATH):
		return
	var f := FileAccess.open(SAVE_PATH, FileAccess.READ)
	if f == null:
		return
	var text := f.get_as_text()
	f.close()
	var data: Variant = JSON.parse_string(text)
	if typeof(data) != TYPE_DICTIONARY:
		return
	var b: Variant = data.get("best", {})
	if typeof(b) == TYPE_DICTIONARY:
		for key in MODES:
			best[key] = int(b.get(key, 0))
	plays = int(data.get("plays", 0))
	total_hits = int(data.get("total_hits", 0))
	total_perfects = int(data.get("total_perfects", 0))
	best_combo = int(data.get("best_combo", 0))


func save_data() -> void:
	var f := FileAccess.open(SAVE_PATH, FileAccess.WRITE)
	if f == null:
		return
	f.store_string(JSON.stringify({
		"best": best,
		"plays": plays,
		"total_hits": total_hits,
		"total_perfects": total_perfects,
		"best_combo": best_combo,
	}, "\t"))
	f.close()


func get_best(mode_key: String) -> int:
	return int(best.get(mode_key, 0))


## Records the end of a run. Returns true when a new personal best was set.
func record_run(mode_key: String, run_score: int, run_hits: int, run_perfects: int, run_combo: int) -> bool:
	plays += 1
	total_hits += run_hits
	total_perfects += run_perfects
	best_combo = maxi(best_combo, run_combo)
	var is_best := run_score > int(best.get(mode_key, 0))
	if is_best:
		best[mode_key] = run_score
	save_data()
	return is_best

extends Node

## Tiny pooled SFX player. Kenney CC0 audio.

const POOL_SIZE := 16

const STREAMS := {
	"click": preload("res://assets/audio/ui_click.ogg"),
	"tick": preload("res://assets/audio/ui_tick.ogg"),
	"select": preload("res://assets/audio/ui_select.ogg"),
	"start": preload("res://assets/audio/start.ogg"),
	"ready": preload("res://assets/audio/ready.ogg"),
	"hit_1": preload("res://assets/audio/hit_1.ogg"),
	"hit_2": preload("res://assets/audio/hit_2.ogg"),
	"hit_3": preload("res://assets/audio/hit_3.ogg"),
	"perfect": preload("res://assets/audio/perfect.ogg"),
	"mistap": preload("res://assets/audio/mistap.ogg"),
	"escape": preload("res://assets/audio/escape.ogg"),
	"glitch": preload("res://assets/audio/glitch.ogg"),
	"victory": preload("res://assets/audio/victory.ogg"),
}

var _players: Array[AudioStreamPlayer] = []
var _cursor := 0


func _ready() -> void:
	process_mode = Node.PROCESS_MODE_ALWAYS
	for i in range(POOL_SIZE):
		var p := AudioStreamPlayer.new()
		p.bus = "Master"
		add_child(p)
		_players.append(p)


func _play(stream_name: String, volume_db: float = -6.0, pitch: float = 1.0) -> void:
	if not STREAMS.has(stream_name):
		return
	var p := _next_player()
	p.stream = STREAMS[stream_name]
	p.volume_db = volume_db
	p.pitch_scale = pitch
	p.play()


func _next_player() -> AudioStreamPlayer:
	for i in range(POOL_SIZE):
		var idx := (_cursor + i) % POOL_SIZE
		if not _players[idx].playing:
			_cursor = (idx + 1) % POOL_SIZE
			return _players[idx]
	_cursor = (_cursor + 1) % POOL_SIZE
	return _players[_cursor]


func play_click() -> void:
	_play("click", -10.0, randf_range(0.98, 1.04))


func play_tick() -> void:
	_play("tick", -9.0, 1.0)


func play_select() -> void:
	_play("select", -7.0, 1.0)


func play_start() -> void:
	_play("start", -4.0, 1.0)
	_play("ready", -8.0, 1.0)


func play_hit(accuracy: float) -> void:
	var idx := randi_range(1, 3)
	_play("hit_%d" % idx, -8.0 + accuracy * 3.0, randf_range(0.94, 1.12))
	if accuracy > 0.82:
		_play("perfect", -9.0, randf_range(0.98, 1.06))


func play_mistap() -> void:
	_play("mistap", -3.0, 1.0)
	_play("glitch", -10.0, 0.8)


func play_escape() -> void:
	_play("escape", -3.0, 0.9)


func play_victory() -> void:
	_play("victory", -3.0, 1.0)

